 private NativeUi ui;private ApiClient api;private UpdateManager updates;private JSONObject data=new JSONObject(),user;private LinearLayout root,body,nav,header;private ScrollView scroll;private ProgressBar loading;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler();private boolean busy,started;private String tab="home",screen="",auth="login",filter="all";private JSONObject selected,draft=new JSONObject();
 private final LinkedHashMap<String,EditText> fields=new LinkedHashMap<>();private final HashMap<String,Spinner> choices=new HashMap<>();private final ArrayList<EditText> companions=new ArrayList<>();private JSONArray cacheUsers;private String avatarData;private ImageView avatarPreview;
 private static final ZoneId CHINA=ZoneId.of("Asia/Shanghai");private static final int TEXT=InputType.TYPE_CLASS_TEXT,PASSWORD=TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD,NUMBER=InputType.TYPE_CLASS_NUMBER;private long lastRender;
 interface Work<T>{T run()throws Exception;}interface Done<T>{void accept(T result)throws Exception;}
 static JSONObject obj(Object... p){return ApiClient.object(p);}static String s(JSONObject o,String k){return o==null||o.isNull(k)?"":o.optString(k,"");}static JSONArray arr(JSONObject o,String k){JSONArray a=o.optJSONArray(k);return a==null?new JSONArray():a;}
 private boolean owner(){return user!=null&&"admin".equals(s(user,"role"));}private boolean manager(){return user!=null&&"manager".equals(s(user,"role"));}
 private String value(String key){EditText e=fields.get(key);return e==null?"":e.getText().toString().trim();}
 private String fmt(String date){try{return Instant.parse(date).atZone(CHINA).format(DateTimeFormatter.ofPattern("yyyy年M月d日 HH:mm"));}catch(Exception e){return date;}}
 private String week(String w){try{LocalDate d=LocalDate.parse(w);return d.format(DateTimeFormatter.ofPattern("M月d日"))+" — "+d.plusDays(6).format(DateTimeFormatter.ofPattern("M月d日"));}catch(Exception e){return "周一至周日 · 北京时间";}}
 private String status(JSONObject b){String v=s(b,"status");return "pending".equals(v)?"等待审批":"approved".equals(v)?"已批准":"completed".equals(v)?"已完成":"cancelled".equals(v)?"已取消":"已拒绝";}
 private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
 private void error(String message){if(!isFinishing())new AlertDialog.Builder(this).setTitle("请确认").setMessage(message).setPositiveButton("知道了",null).show();}
 private <T> void async(Work<T> action,Done<T> done){if(busy)return;busy=true;if(loading!=null)loading.setVisibility(View.VISIBLE);enable(body,false);worker.execute(()->{try{T result=action.run();handler.post(()->{if(isDestroyed())return;busy=false;if(loading!=null)loading.setVisibility(View.INVISIBLE);enable(body,true);try{done.accept(result);}catch(Exception e){error(e.getMessage()==null?"操作失败，请重试。":e.getMessage());}});}catch(Exception e){handler.post(()->{if(isDestroyed())return;busy=false;if(loading!=null)loading.setVisibility(View.INVISIBLE);enable(body,true);if(e instanceof ApiClient.SessionExpired){user=null;data=new JSONObject();screen="";render();}error(e instanceof java.net.SocketTimeoutException?"连接超时，请检查网络后重试。":e.getMessage()==null?"网络连接失败，请重试。":e.getMessage());});}});}
 private void enable(View view,boolean enabled){if(view==null)return;view.setEnabled(enabled);if(view instanceof android.view.ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)enable(((ViewGroup)view).getChildAt(i),enabled);}
 private void load(){async(()->api.state(),state->{data=state;user=state.optJSONObject("user");NoticeNotifier.accept(MainActivity.this,state);if(user==null)screen="";else if(user.optBoolean("mustBindEmail"))screen="bind";else if(user.optBoolean("mustChange"))screen="password";render();NoticeNotifier.ask(this);});}
 private void mutate(JSONObject payload,Runnable after){async(()->{api.action(payload);return api.state();},state->{data=state;user=state.optJSONObject("user");NoticeNotifier.accept(MainActivity.this,state);after.run();if(user!=null&&user.optBoolean("mustBindEmail"))screen="bind";else if(user!=null&&user.optBoolean("mustChange"))screen="password";render();NoticeNotifier.ask(this);});}
 private void send(JSONObject payload,String message){async(()->api.action(payload),r->toast(message));}
 @Override public void onCreate(Bundle state){Appearance.apply(this);super.onCreate(state);ui=new NativeUi(this);api=new ApiClient(this);updates=new UpdateManager(this);if(state!=null){tab=state.getString("tab","home");screen=state.getString("screen","");try{draft=new JSONObject(state.getString("draft","{}"));selected=new JSONObject(state.getString("selected","{}"));}catch(Exception ignored){}}
  if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(ui.bg);getWindow().getDecorView().setSystemUiVisibility(ui.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  if("messages".equals(getIntent().getStringExtra("destination")))tab="messages";render();load();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->back());
 }
 private void render(){
  fields.clear();choices.clear();companions.clear();root=ui.column();root.setBackgroundColor(ui.bg);setContentView(root);
  if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()),ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(b.left,b.top,b.right,Math.max(b.bottom,ime.bottom));return insets;});
  else root.setFitsSystemWindows(true);
  header=ui.row();header.setPadding(ui.dp(16),ui.dp(8),ui.dp(12),ui.dp(8));
  if(!screen.isEmpty())header.addView(iconButton("back","返回",()->back()),new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));
  TextView brand=ui.text(screen.isEmpty()?"王亦达 · 放纵餐预约":"用餐与生活",15,ui.muted,true);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));View menu=iconButton("more","更多选项",()->menu());header.addView(menu,new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));root.addView(header);
  loading=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);loading.setIndeterminate(true);loading.setVisibility(busy?View.VISIBLE:View.INVISIBLE);root.addView(loading,new LinearLayout.LayoutParams(-1,ui.dp(2)));
  scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);body=ui.column();body.setPadding(ui.dp(20),ui.dp(20),ui.dp(20),ui.dp(24));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(user==null){authView();return;}
  if(!screen.isEmpty()){if("appearance".equals(screen))Appearance.settings(this,body,ui);else if("updates".equals(screen))updates.render(body,ui);else if("notifications".equals(screen))NoticeNotifier.settings(this,body,ui);else if("book".equals(screen)||"self".equals(screen)||"edit".equals(screen))bookingForm();else if("bind".equals(screen)||"email".equals(screen))emailForm();else if("password".equals(screen))passwordForm();else if("profile".equals(screen))profileForm();else if("username".equals(screen))usernameForm();else if("quota".equals(screen))quotaForm();else if("editUser".equals(screen))userForm();else if("detail".equals(screen))detailView();else if("users".equals(screen))usersView();else if("delivery".equals(screen)||"audit".equals(screen))logsView();return;}
  if("home".equals(tab))home();else if("bookings".equals(tab))bookingList(false);else if("records".equals(tab))bookingList(true);else if("messages".equals(tab))messages();else profile();
  navigation();lastRender=System.currentTimeMillis();
 }
 private View iconButton(String name,String description,Runnable action){FrameLayout b=new FrameLayout(this);b.setBackground(ui.shape(ui.bg,24));b.setContentDescription(description);b.setOnClickListener(v->action.run());b.addView(ui.icon(name,ui.primary),new FrameLayout.LayoutParams(-1,-1));return b;}
 private void menu(){PopupMenu menu=new PopupMenu(this,header.getChildAt(header.getChildCount()-1));menu.getMenu().add("同步最新数据").setOnMenuItemClickListener(i->{if(screen.isEmpty())load();else toast("请先保存或返回，避免丢失正在填写的内容。");return true;});menu.getMenu().add("关于应用").setOnMenuItemClickListener(i->{new AlertDialog.Builder(this).setTitle("王亦达放纵餐预约 2.3").setMessage("原生 Android 客户端\n账号与记录和网站同步\n消息与邮件沿用现有通知服务").setPositiveButton("知道了",null).show();return true;});menu.show();}
 private void navigation(){nav=ui.row();nav.setBackgroundColor(ui.card);nav.setPadding(ui.dp(8),ui.dp(8),ui.dp(8),ui.dp(8));String[] keys={"home","bookings","records","messages","profile"},labels={"概览","预约","记录","消息","我的"},icons={"home","calendar","fire","message","person"};for(int i=0;i<keys.length;i++){final String key=keys[i];LinearLayout item=ui.column();item.setGravity(Gravity.CENTER);boolean active=tab.equals(key);FrameLayout capsule=new FrameLayout(this);capsule.setBackground(ui.shape(active?ui.tonal:ui.card,24));capsule.addView(ui.icon(icons[i],active?ui.primary:ui.muted),new FrameLayout.LayoutParams(-1,-1));item.addView(capsule,new LinearLayout.LayoutParams(ui.dp(60),ui.dp(32)));TextView text=ui.text(labels[i],12,active?ui.primary:ui.muted,active);text.setGravity(Gravity.CENTER);ui.gap(item,5);item.addView(text);item.setContentDescription(labels[i]);item.setOnClickListener(v->{if(busy)return;tab=key;filter="all";render();});nav.addView(item,new LinearLayout.LayoutParams(0,ui.dp(72),1));}root.addView(nav);}
 private EditText field(LinearLayout parent,String key,String label,String initial,int type){EditText e=ui.input(parent,label,initial,type);fields.put(key,e);return e;}
 private boolean required(String... keys){for(String key:keys){EditText e=fields.get(key);if(e!=null&&e.getText().toString().trim().isEmpty()){e.setError("请填写此项");e.requestFocus();return false;}}return true;}
 private JSONObject form(String action){JSONObject b=obj("action",action);for(String key:fields.keySet())try{b.put(key,value(key));}catch(Exception ignored){}return b;}
 private void open(String next){draft=new JSONObject();avatarData=null;screen=next;render();}
 private void done(){screen="";draft=new JSONObject();toast("已保存");}
 private void authView(){
  ui.gap(body,24);View leaf=ui.icon("leaf",ui.primary);leaf.setBackground(ui.shape(ui.tonal,32));body.addView(leaf,new LinearLayout.LayoutParams(ui.dp(64),ui.dp(64)));ui.gap(body,24);
  boolean login="login".equals(auth)||"manager".equals(auth);ui.title(body,login?"从容安排，\n好好吃饭。":"register".equals(auth)?"开启你的预约":"找回账号",login?"自律有节奏，享受有分寸。":"通过邮箱验证码安全验证账号");
  LinearLayout box=ui.card(body);box.addView(ui.text(login?"欢迎回来":"register".equals(auth)?"注册账号":"重置密码",22,ui.text,true));
  if("register".equals(auth))field(box,"username","用户名 · 字母、数字或下划线","",TEXT);
  field(box,"email",login?"用户名或邮箱":"邮箱地址","",login?TEXT:TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
  if(!login){field(box,"code","6 位邮箱验证码","",NUMBER);ui.fullButton(box,"发送验证码",false,()->{if(required("email"))send(obj("action","sendCode","email",value("email"),"purpose","reset".equals(auth)?"reset":"register"),"验证码已发送，请检查邮箱。");});}
  field(box,"password",login?"密码":"密码 · 至少10位","",PASSWORD);if(!login)field(box,"confirm","确认密码","",PASSWORD);
  ui.fullButton(box,login?"登录":"register".equals(auth)?"验证并注册":"验证并重置密码",true,()->{if(!required("email","password")||!login&&!required("code"))return;if(!login&&!value("password").equals(value("confirm"))){error("两次密码不一致。");return;}JSONObject b=form(login?"login":"verify");try{b.put("managerLogin","manager".equals(auth));b.put("purpose","reset".equals(auth)?"reset":"register");}catch(Exception ignored){}mutate(b,()->{screen="";if("reset".equals(auth))auth="login";});});
  ui.gap(body,12);for(String[] link:new String[][]{{"login","返回登录"},{"register","注册新账号"},{"reset","忘记密码"}}){if(!auth.equals(link[0]))ui.fullButton(body,link[1],false,()->{auth=link[0];render();});}ui.gap(body,12);ui.fullButton(body,"manager".equals(auth)?"返回普通登录":"管理员入口",false,()->{auth="manager".equals(auth)?"login":"manager";render();});

 }
 private JSONObject currentQuota(){for(int i=0;i<arr(data,"quotas").length();i++){JSONObject q=arr(data,"quotas").optJSONObject(i);if(s(q,"week").equals(s(data,"week")))return q;}return new JSONObject();}
 private void home(){
  ui.title(body,"给生活，\n留一点平衡。",(owner()?"王亦达专属空间":manager()?"管理员工作台":"你好，"+(s(user,"nickname").isEmpty()?s(user,"username"):s(user,"nickname")))+" · "+week(s(data,"week")));
  LinearLayout hero=ui.card(body);hero.setBackground(ui.shape(ui.tonal,32));hero.addView(ui.text("本周剩余额度",15,ui.primary,true));ui.gap(hero,12);int cap=data.optInt("weekLimit",2),count=currentQuota().optInt("count");hero.addView(ui.text(String.valueOf(cap-count),64,cap-count<0?ui.error:ui.primary,true));hero.addView(ui.text("已完成 "+currentQuota().optInt("used")+" 次  ·  已预留 "+currentQuota().optInt("reserved")+" 次  ·  额度 "+cap+" 次",14,ui.muted,false));ui.gap(hero,16);hero.addView(ui.text(cap-count<0?"自主记录已超额，请留意本周饮食安排。":"认真坚持，也适度享受。",16,ui.text,false));
  if(!manager())ui.fullButton(body,owner()?"＋ 记录一次放纵餐":"＋ 发起新的预约",true,()->open(owner()?"self":"book"));
  JSONObject stats=data.optJSONObject("mealStats");if(stats!=null){LinearLayout c=ui.card(body);ui.gap(c,2);c.addView(ui.text("本周热量",14,ui.muted,true));c.addView(ui.text(stats.optLong("weekCalories")+" 千卡",30,ui.text,true));if(stats.optInt("missingCalories")>0){c.addView(ui.body(stats.optInt("missingCalories")+" 次已完成用餐待补填热量"));ui.fullButton(c,"查看用餐记录",false,()->{tab="records";render();});}}
  if(manager()){ui.fullButton(body,"管理周额度",false,()->open("quota"));ui.fullButton(body,"查看所有用户",false,()->open("users"));ui.fullButton(body,"邮件投递状态",false,()->open("delivery"));ui.fullButton(body,"管理操作记录",false,()->open("audit"));}
  ui.gap(body,16);body.addView(ui.text("接下来的安排",22,ui.text,true));ui.gap(body,12);int shown=0;JSONArray bookings=arr(data,"bookings");for(int i=0;i<bookings.length()&&shown<3;i++){JSONObject b=bookings.optJSONObject(i);if(Arrays.asList("pending","approved").contains(s(b,"status"))){bookingCard(b,false);shown++;}}if(shown==0)empty("还没有进行中的预约","为下一次值得期待的相聚，留一点空间。");
 }
 private void empty(String title,String subtitle){LinearLayout c=ui.card(body);c.addView(ui.text(title,19,ui.text,true));ui.gap(c,10);c.addView(ui.text(subtitle,15,ui.muted,false));}
 private void bookingList(boolean records){ui.title(body,records?"放纵餐记录":owner()||manager()?"预约管理":"我的预约",records?"每一餐，都有迹可循。":"按用餐日期所在的自然周安排额度。");
  if(records){JSONObject st=data.optJSONObject("mealStats");if(st!=null){LinearLayout c=ui.card(body);c.setBackground(ui.shape(ui.tonal,28));c.addView(ui.text("累计摄入热量",14,ui.primary,true));c.addView(ui.text(st.optLong("totalCalories")+" 千卡",36,ui.primary,true));c.addView(ui.body(st.optInt("meals")+" 次用餐 · "+st.optInt("missingCalories")+" 次热量待补填"));}if(owner())ui.fullButton(body,"＋ 自主填写记录",true,()->open("self"));}
  else if(!owner()&&!manager())ui.fullButton(body,"＋ 新建预约",true,()->open("book"));
  LinearLayout chips=ui.row();HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);hs.addView(chips);for(String[] f:records?new String[][]{{"all","全部"},{"week","本周"},{"missing","待补热量"}}:new String[][]{{"all","全部"},{"pending","待审批"},{"approved","已批准"},{"cancelled","已取消"},{"rejected","已拒绝"}}){Button chip=ui.button(f[1],filter.equals(f[0]),()->{filter=f[0];render();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(0,ui.dp(12),ui.dp(8),ui.dp(16));chips.addView(chip,p);}body.addView(hs);
  ArrayList<JSONObject> list=new ArrayList<>();JSONArray bs=arr(data,"bookings");for(int i=0;i<bs.length();i++){JSONObject b=bs.optJSONObject(i);boolean complete="completed".equals(s(b,"status"));if(complete!=records)continue;if(!"all".equals(filter)&&!(records?("week".equals(filter)?s(b,"week").equals(s(data,"week")):b.isNull("calories")):s(b,"status").equals(filter)))continue;list.add(b);}list.sort((a,b)->s(b,"meal_at").compareTo(s(a,"meal_at")));for(JSONObject b:list)bookingCard(b,records);if(list.isEmpty())empty("暂无符合条件的记录","新的用餐安排会在这里显示。");
 }
 private void bookingCard(JSONObject b,boolean record){LinearLayout c=ReservationCard.render(ui,body,b);ui.fullButton(c,"查看详情与操作",false,()->{selected=b;open("detail");});}
 private void detailView(){if(selected==null){screen="";render();return;}JSONObject b=selected;ui.title(body,"completed".equals(s(b,"status"))?"放纵餐记录":"预约详情",s(b,"week")+" 当周");LinearLayout c=ReservationCard.render(ui,body,b);
  if(!b.isNull("latitude"))ui.fullButton(c,"在地图中查看位置",false,()->map(b));String status=s(b,"status");
  if("completed".equals(status)){if(owner()&&b.isNull("calories"))ui.fullButton(body,"补填本人摄入热量",true,()->calories(b,"fillCalories"));}
  if(owner()&&"pending".equals(status)){ui.fullButton(body,"批准预约",true,()->confirm("批准此预约？","批准后先占用用餐周名额。",()->mutate(obj("action","approve","id",s(b,"id")),()->screen="")));ui.fullButton(body,"拒绝预约",false,()->reason(b,"reject",false));}
  if(owner()&&"approved".equals(status)){try{if(Instant.parse(s(b,"meal_at")).isBefore(Instant.now()))ui.fullButton(body,"填写热量并完成用餐",true,()->calories(b,"complete"));}catch(Exception ignored){}}
  if(!manager()&&Arrays.asList("pending","approved").contains(status))ui.fullButton(body,"取消预约",false,()->confirm("取消这次预约？","已占用的名额会返还原预约周。",()->mutate(obj("action","cancel","id",s(b,"id")),()->screen="")));
  if("self".equals(s(b,"source")))body.addView(ui.text("自主记录提交后，仅管理员可修改或取消。",14,ui.muted,false));
  if(manager()){ui.fullButton(body,"编辑记录",true,()->open("edit"));if(Arrays.asList("pending","approved","completed").contains(status))ui.fullButton(body,"取消记录并返还名额",false,()->reason(b,"manageCancel",true));}
 }
 private void confirm(String title,String message,Runnable action){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("确认",(d,w)->action.run()).setNegativeButton("再想想",null).show();}
 private void reason(JSONObject b,String action,boolean required){LinearLayout box=ui.column();box.setPadding(ui.dp(24),0,ui.dp(24),0);EditText e=ui.input(box,"原因"+(required?"":"（选填）"),"",TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("reject".equals(action)?"拒绝预约":"取消记录").setView(box).setPositiveButton("确认",null).setNegativeButton("返回",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String reason=e.getText().toString().trim();if(required&&reason.isEmpty()){e.setError("请填写取消原因");return;}dialog.dismiss();mutate(obj("action",action,"id",s(b,"id"),"reason",reason),()->screen="");}));dialog.show();}
 private void calories(JSONObject b,String action){LinearLayout box=ui.column();box.setPadding(ui.dp(24),0,ui.dp(24),0);EditText e=ui.input(box,"王亦达本人摄入热量 · 千卡","",NUMBER);AlertDialog d=new AlertDialog.Builder(this).setTitle("complete".equals(action)?"完成这次用餐":"补填热量").setView(box).setPositiveButton("保存",null).setNegativeButton("返回",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(btn->{try{int n=Integer.parseInt(e.getText().toString());if(n<1||n>100000)throw new Exception();d.dismiss();mutate(obj("action",action,"id",s(b,"id"),"calories",n),()->{screen="";tab="records";});}catch(Exception ex){e.setError("请输入1至100000的整数");}}));d.show();}
 private String mealLabel(String type){return "lunch".equals(type)?"午餐":"late".equals(type)?"夜宵":"dinner".equals(type)?"晚餐":"未注明";}
 private void map(JSONObject b){String uri="https://uri.amap.com/marker?position="+b.optDouble("longitude")+","+b.optDouble("latitude")+"&name="+Uri.encode(s(b,"restaurant"))+"&coordinate="+("gcj02".equals(s(b,"coordinate_system"))?"gaode":"wgs84")+"&callnative=1";external(uri);}
 private void external(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){toast("没有可打开地图的应用");}}
 private void messages(){ui.title(body,"消息通知","预约邀请、审批进度与用餐提醒");if(!manager())ui.fullButton(body,"全部标记为已读",false,()->mutate(obj("action","read"),()->{}));JSONArray list=arr(data,"notices");if(list.length()==0)empty("暂时没有消息","重要的用餐动态会在这里告诉你。");for(int i=0;i<list.length();i++){JSONObject n=list.optJSONObject(i);LinearLayout c=ui.card(body);if(n.optInt("read")==0)c.addView(ui.text("● 未读",12,ui.primary,true));ui.gap(c,8);TextView message=ui.body(s(n,"message"));message.setTextIsSelectable(true);c.addView(message);ui.gap(c,12);c.addView(ui.text(fmt(s(n,"created")),13,ui.muted,false));}}
 private void profile(){ui.title(body,"我的空间",s(user,"username")+" · "+(owner()?"王亦达":manager()?"管理员":"预约用户"));LinearLayout card=ui.card(body);avatarPreview=new ImageView(this);avatarPreview.setScaleType(ImageView.ScaleType.CENTER_CROP);avatarPreview.setBackground(ui.shape(ui.tonal,36));avatarPreview.setClipToOutline(true);card.addView(avatarPreview,new LinearLayout.LayoutParams(ui.dp(72),ui.dp(72)));loadAvatar();ui.gap(card,16);card.addView(ui.text(s(user,"nickname").isEmpty()?s(user,"username"):s(user,"nickname"),24,ui.text,true));card.addView(ui.text(s(user,"email"),15,ui.muted,false));if(!manager()){ui.fullButton(body,"修改昵称与头像",false,()->open("profile"));ui.fullButton(body,"修改用户名",false,()->open("username"));ui.fullButton(body,"更换邮箱",false,()->open("email"));}ui.fullButton(body,"修改密码",false,()->open("password"));
  if(manager()){ui.fullButton(body,"用户信息管理",false,()->open("users"));ui.fullButton(body,"设置周额度",false,()->open("quota"));ui.fullButton(body,"邮件投递记录",false,()->open("delivery"));ui.fullButton(body,"管理员操作记录",false,()->open("audit"));}
  ui.fullButton(body,"外观设置 · 明暗与颜色",false,()->open("appearance"));ui.fullButton(body,"检查应用更新",false,()->open("updates"));ui.fullButton(body,"系统通知设置",false,()->open("notifications"));ui.fullButton(body,"退出登录",false,()->confirm("退出当前账号？","用餐数据会保存在服务器。",()->mutate(obj("action","logout"),()->{api.clear();screen="";tab="home";})));}
