 private void passwordForm(){ui.title(body,user.optBoolean("mustChange")?"设置新的密码":"修改密码","至少10位，保存后其他登录会话将退出。");field(body,"oldPassword","当前密码","",PASSWORD);field(body,"password","新密码","",PASSWORD);field(body,"confirm","再次输入新密码","",PASSWORD);ui.fullButton(body,"保存密码",true,()->{if(!required("oldPassword","password","confirm"))return;if(!value("password").equals(value("confirm"))){error("两次密码不一致。");return;}mutate(form("password"),()->done());});}
