 private void profileForm(){ui.title(body,"个人资料","让每一次相聚，都有熟悉的名字。");avatarPreview=new ImageView(this);avatarPreview.setBackground(ui.shape(ui.tonal,40));avatarPreview.setClipToOutline(true);avatarPreview.setScaleType(ImageView.ScaleType.CENTER_CROP);body.addView(avatarPreview,new LinearLayout.LayoutParams(ui.dp(80),ui.dp(80)));loadAvatar();ui.fullButton(body,"选择新的头像",false,()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,101);});field(body,"nickname","昵称",s(user,"nickname"),TEXT);ui.fullButton(body,"保存个人资料",true,()->{if(!required("nickname"))return;JSONObject p=form("profile");try{if(avatarData!=null)p.put("avatarData",avatarData);}catch(Exception ignored){}mutate(p,()->done());});}
 private void loadAvatar(){String path=s(user,"avatarUrl");final ImageView target=avatarPreview;if(path.isEmpty()||target==null)return;worker.execute(()->{try{byte[] bytes=api.avatar(path);Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);handler.post(()->{if(!isDestroyed())target.setImageBitmap(bitmap);});}catch(Exception ignored){}});}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==102&&result==RESULT_OK&&intent!=null){try{JSONObject place=new JSONObject(intent.getStringExtra("place"));EditText name=fields.get("restaurant"),address=fields.get("address");if(name!=null)name.setText(s(place,"name"));if(address!=null)address.setText(s(place,"address"));draft.put("latitude",place.getDouble("lat"));draft.put("longitude",place.getDouble("lng"));draft.put("coordinateSystem","gcj02");}catch(Exception e){error("地点读取失败，请重新选择。");}}
  if(request==101&&result==RESULT_OK&&intent!=null){final Uri uri=intent.getData();async(()->{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,options);}if(options.outWidth<=0||options.outHeight<=0)throw new IOException("无法读取这张图片。");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>512)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bmp;try(InputStream in=getContentResolver().openInputStream(uri)){bmp=BitmapFactory.decodeStream(in,null,options);}if(bmp==null)throw new IOException("图片无法解码。");int side=Math.min(bmp.getWidth(),bmp.getHeight());Bitmap cropped=Bitmap.createScaledBitmap(Bitmap.createBitmap(bmp,(bmp.getWidth()-side)/2,(bmp.getHeight()-side)/2,side,side),256,256,true);ByteArrayOutputStream out=new ByteArrayOutputStream();cropped.compress(Bitmap.CompressFormat.JPEG,85,out);if(out.size()>131072)throw new IOException("图片过大，请选择其他头像。");return out.toByteArray();},bytes->{avatarData="data:image/jpeg;base64,"+android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP);if(avatarPreview!=null)avatarPreview.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));});}}
