 private void usersView(){ui.title(body,"用户管理","账号与角色信息");JSONArray users=arr(data,"users");for(int i=0;i<users.length();i++){JSONObject u=users.optJSONObject(i);LinearLayout c=ui.card(body);c.addView(ui.text(s(u,"username"),22,ui.text,true));c.addView(ui.body(s(u,"email")+"\n"+s(u,"nickname")+" · "+s(u,"role")+(u.optInt("disabled")==1?" · 已停用":"")));ui.fullButton(c,"编辑用户",false,()->{selected=u;open("editUser");});ui.fullButton(c,"查看用户记录与消息",false,()->{LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(12),ui.dp(20),ui.dp(20));for(int n=0;n<arr(data,"bookings").length();n++){JSONObject b=arr(data,"bookings").optJSONObject(n);if(s(b,"user_id").equals(s(u,"id"))){box.addView(ui.text(s(b,"restaurant")+" · "+status(b),18,ui.text,true));box.addView(ui.body(fmt(s(b,"meal_at"))+"\n热量："+(b.isNull("calories")?"待补填":s(b,"calories"))+"\n姓名："+s(b,"name")+"\n备注："+s(b,"notes")+"\n交通方式："+BookingLabels.transport(s(b,"transport_mode"))+"\n预估人均消费："+(b.isNull("estimated_cost_cents")?"未填写":"¥"+BookingLabels.amount(b.optLong("estimated_cost_cents"))+" / 人")));ui.gap(box,16);}}for(int n=0;n<arr(data,"notices").length();n++){JSONObject notice=arr(data,"notices").optJSONObject(n);if(s(notice,"user_id").equals(s(u,"id"))){box.addView(ui.body(s(notice,"message")));ui.gap(box,14);}}ScrollView sv=new ScrollView(this);sv.addView(box);new AlertDialog.Builder(this).setTitle(s(u,"username")).setView(sv).setPositiveButton("关闭",null).show();});}}
 private void logsView(){boolean mail="delivery".equals(screen);ui.title(body,mail?"邮件投递":"管理操作记录",mail?"发送成功表示发信服务已接收。":"最近的管理员操作与修改详情。");JSONArray list=arr(data,mail?"mailDeliveries":"audit");for(int i=0;i<list.length();i++){JSONObject r=list.optJSONObject(i);LinearLayout c=ui.card(body);c.addView(ui.text(mail?s(r,"recipient"):s(r,"action"),18,ui.text,true));TextView detail=ui.body(mail?("状态："+s(r,"status")+"\n尝试次数："+r.optInt("attempts")+"\n"+s(r,"last_error")+"\n"+s(r,"sent_at")):("操作人："+s(r,"actor")+"\n"+fmt(s(r,"created"))+"\n"+s(r,"details")));detail.setTextIsSelectable(true);c.addView(detail);}if(list.length()==0)empty("暂无记录","后续更新会在这里显示。");}
 private final Runnable poll=new Runnable(){public void run(){if(started){if(!busy&&user!=null&&screen.isEmpty())worker.execute(()->{try{JSONObject state=api.state();handler.post(()->{if(!isDestroyed()&&!busy&&screen.isEmpty()&&!state.toString().equals(data.toString())){data=state;user=state.optJSONObject("user");NoticeNotifier.accept(MainActivity.this,state);render();}});}catch(Exception ignored){}});handler.postDelayed(this,30000);}}};
 @Override protected void onStart(){super.onStart();started=true;handler.postDelayed(poll,30000);updates.check(false);}
 @Override protected void onStop(){started=false;handler.removeCallbacks(poll);super.onStop();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if("messages".equals(intent.getStringExtra("destination"))){tab="messages";screen="";render();load();}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==301){NoticeNotifier.schedule(this);PushBridge.offer(this);if("notifications".equals(screen))render();}}
 private void back(){if(busy)return;if(!screen.isEmpty()){if("bind".equals(screen)&&user!=null&&user.optBoolean("mustBindEmail")||"password".equals(screen)&&user!=null&&user.optBoolean("mustChange")){confirm("退出账号？","请完成账号验证后再使用。",()->mutate(obj("action","logout"),()->{screen="";api.clear();}));return;}if(Arrays.asList("book","self","edit","email","profile","password","username","quota","editUser").contains(screen)){confirm("返回上一页？","未保存的内容将不会提交。",()->{screen="";draft=new JSONObject();render();});}else{screen="";draft=new JSONObject();render();}}else if(!"home".equals(tab)){tab="home";render();}else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle state){if(Arrays.asList("book","self","edit").contains(screen)){draft=BookingForms.collect(this,false);state.putString("draft",draft.toString());}state.putString("tab",tab);state.putString("screen",screen);if(selected!=null)state.putString("selected",selected.toString());super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(updates!=null)updates.close();worker.shutdownNow();super.onDestroy();}
 // Package-visible access keeps form code focused and avoids exposing credentials.
 NativeUi ui(){return ui;}LinearLayout body(){return body;}JSONObject user(){return user;}JSONObject data(){return data;}JSONObject selected(){return selected;}JSONObject draft(){return draft;}String screen(){return screen;}EditText addField(LinearLayout p,String k,String l,String v,int t){return field(p,k,l,v,t);}String val(String k){return value(k);}boolean need(String... k){return required(k);}void save(JSONObject b){mutate(b,()->{done();tab="selfRecord".equals(s(b,"action"))?"records":tab;});}void notifyError(String m){error(m);}HashMap<String,Spinner> choices(){return choices;}ArrayList<EditText> companions(){return companions;}LinkedHashMap<String,EditText> fields(){return fields;}void pickPlace(){Intent i=new Intent(this,PlacePickerActivity.class);startActivityForResult(i,102);}
